// One base per probe lane — “MultiTurnResult“, “MultiModalResult“,
// “AudioProbeResult“ — so no lane's verdict fields are re-declared here. The audio
// base is exactly what “probe_audio_support“ returns, so the copy from lane verdict
// to stored metadata cannot drift. Base order fixes the serialized field order, which
// the Restate journal is sensitive to; “AudioProbeResult“ records why inheriting it
// is safe for journals predating audio.
// .
type TargetMetadata struct {
	// Whether target supports multi-turn conversations (Probe 2 result)
	MultiTurn *bool `json:"multi_turn,omitempty"`
	// Concise error message if Probe 2 failed
	MultiTurnErrorMessage aisec.Optional[string] `json:"multi_turn_error_message,omitempty"`
	// Whether the target accepted a sample file attack at validation time (Probe 3). When False, scans against this target run text-only.
	SupportsMultimodalFiles *bool `json:"supports_multimodal_files,omitempty"`
	// Concise error message if the multimodal file probe failed
	SupportsMultimodalFilesErrorMessage aisec.Optional[string] `json:"supports_multimodal_files_error_message,omitempty"`
	// Whether the target accepted a sample audio clip at validation time (Probe 1 of the audio lane). False means it rejected the clip; None means no verdict was reached — see audio_probe_error, which is set on every such path.
	AudioProbePassed aisec.Optional[bool] `json:"audio_probe_passed,omitempty"`
	// Concise error message if the audio probe failed or was skipped
	AudioProbeError aisec.Optional[string] `json:"audio_probe_error,omitempty"`
	// Whether the target held an AUDIO conversation across turns (Probe 2 of the audio lane). None means it was not probed — no verdict from Probe 1, no multi-turn config, or the transport has no audio multi-turn.
	AudioMultiTurnProbePassed aisec.Optional[bool] `json:"audio_multi_turn_probe_passed,omitempty"`
	// Concise error message if the audio multi-turn probe failed
	AudioMultiTurnProbeError aisec.Optional[string] `json:"audio_multi_turn_probe_error,omitempty"`
	// Current rate limit value
	RateLimit aisec.Optional[int64] `json:"rate_limit,omitempty"`
	// Whether rate limiting is enabled
	RateLimitEnabled *bool `json:"rate_limit_enabled,omitempty"`
	// HTTP status code for rate limit errors
	RateLimitErrorCode aisec.Optional[int64] `json:"rate_limit_error_code,omitempty"`
	// JSON structure of rate limit error response
	RateLimitErrorJSON aisec.Optional[map[string]any] `json:"rate_limit_error_json,omitempty"`
	// Raw error message string for rate limit errors
	RateLimitErrorMessage aisec.Optional[string] `json:"rate_limit_error_message,omitempty"`
	// Whether content filtering is enabled
	ContentFilterEnabled *bool `json:"content_filter_enabled,omitempty"`
	// HTTP status code for content filter errors
	ContentFilterErrorCode aisec.Optional[int64] `json:"content_filter_error_code,omitempty"`
	// JSON structure of content filter error response
	ContentFilterErrorJSON aisec.Optional[map[string]any] `json:"content_filter_error_json,omitempty"`
	// Raw error message string for content filter errors
	ContentFilterErrorMessage aisec.Optional[string] `json:"content_filter_error_message,omitempty"`
	ProbeMessage              *string                `json:"probe_message,omitempty"`
	// Request timeout in seconds
	RequestTimeout *float64 `json:"request_timeout,omitempty"`
	// Whether the target accepts audio attacks (customer-declared on the connection config). When False, scans against this target skip audio attacks and run text/file-only.
	SupportsAudio *bool `json:"supports_audio,omitempty"`
	// Wire format (WAV/MP3/PCM16) the target accepts; selects which per-format corpus variant mint attaches. None when supports_audio is False.
	AudioFormat aisec.Optional[AudioFormat] `json:"audio_format,omitempty"`
	// Whether the target accepts text attacks. Defaults True (text is the baseline modality). When False, scans skip text/{INPUT} attacks and run file/audio-only — enabling audio-only or file-only targets.
	SupportsText *bool `json:"supports_text,omitempty"`
}

